# Final Diagnostic Script for Pure-MLS Interop (Alice Identity)
from pure_mls.extensions import ExtensionType
from pure_mls.group import GroupInfo
from pure_mls.keys import SignatureKey
from pure_mls.tree import LeafNode, RatchetTree


def _h(s):
	return bytes.fromhex(s)


# Vector welcome-0 Alice
alice_sig_priv_hex = "08c760e174e466ec33ff13eb72eadd44e1b7842bc5b25cfe1ebe755733f7b26c"
pub_key_hex = "9cf32f91d3c021765b082877a4807b69fff7e795241e423d82920618c20fbf1d"
pub_key_bytes = _h(pub_key_hex)

# Verify derivation
print("--- Derivation Check ---")
try:
	local_sig_key = SignatureKey.from_private_bytes(_h(alice_sig_priv_hex))
	derived_pub = local_sig_key.public_bytes()
	print(f"Derived Pub:  {derived_pub.hex()}")
	print(f"Expected Pub: {pub_key_hex}")
	if derived_pub.hex() == pub_key_hex:
		print("MATCH: Key derivation succeeds!")
	else:
		print("MISMATCH: Key derivation failed!")
except Exception as e:
	print(f"Derivation ERROR: {e}")

# Parse GroupInfo from the hex we know is correct
gi_bytes = _h(
	""
)
pub_key_hex = "9cf32f91d3c021765b082877a4807b69fff7e795241e423d82920618c20fbf1d"
pub_key_bytes = _h(pub_key_hex)

# Verify derivation
print("--- Derivation Check ---")
try:
	local_sig_key = SignatureKey.from_private_bytes(_h(alice_sig_priv_hex))
	derived_pub = local_sig_key.public_bytes()
	print(f"Derived Pub:  {derived_pub.hex()}")
	print(f"Expected Pub: {pub_key_hex}")
	if derived_pub.hex() == pub_key_hex:
		print("MATCH: Key derivation succeeds!")
	else:
		print("MISMATCH: Key derivation failed!")
except Exception as e:
	print(f"Derivation ERROR: {e}")

# Parse GroupInfo
gi = GroupInfo.from_bytes(gi_bytes)
print(f"Signer in GroupInfo: {gi.signer}")

# Parse RatchetTree from the first extension
tree_ext_type, tree_ext_data = gi.extensions[0]
if tree_ext_type != ExtensionType.RATCHET_TREE:
	print(f"ERROR: First extension is not RATCHET_TREE, it is {tree_ext_type}")
else:
	tree = RatchetTree.from_bytes(tree_ext_data)
	print(f"Tree parsed with {len(tree.nodes)} nodes.")

	# ID search
	print(f"Alice expected Sig Pub: {pub_key_hex}")

	matches = []
	for i, node in enumerate(tree.nodes):
		if i % 2 == 0 and isinstance(node, LeafNode):
			if node.signature_key == pub_key_bytes:
				matches.append(i)

	if matches:
		print(f"SUCCESS: Alice found at indices {matches}")
	else:
		print("FAILURE: Alice NOT found in tree nodes!")
